create table if not exists room_chat (id uuid primary key default gen_random_uuid(), room_id uuid references classroom_rooms(id) on delete cascade, sender_id uuid, message text not null check (char_length(message) <= 1000), moderation_status text default 'pending', flag_id uuid, created_at timestamptz default now()); alter table room_chat enable row level security; create index if not exists idx_room_chat_room_created on room_chat(room_id,created_at);
